import fs from 'fs';

const oldFixture: Record<string, unknown>[] = JSON.parse(
    fs.readFileSync(
        './src/tests/services/data/PlayerRecord.test.json',
        'utf8',
    ),
);
const newSnapshot: Record<string, unknown>[] = JSON.parse(
    fs.readFileSync('./db-snapshot/PlayerRecord.json', 'utf8'),
);

const key = (r: Record<string, unknown>) =>
    `${r.playerId as number}-${r.gameDayId as number}-${r.year as number}`;

const newByKey = new Map<string, Record<string, unknown>>();
for (const r of newSnapshot) newByKey.set(key(r), r);

let matched = 0;
let missing = 0;
let mismatched = 0;
const mismatchExamples: unknown[] = [];

const commonFields = [
    'responses',
    'played',
    'won',
    'drawn',
    'lost',
    'rankPoints',
    'rankAverages',
    'rankAveragesUnqualified',
    'rankStalwart',
    'rankSpeedy',
    'rankSpeedyUnqualified',
    'rankPub',
];

for (const oldRow of oldFixture) {
    const k = key(oldRow);
    const newRow = newByKey.get(k);
    if (!newRow) {
        missing++;
        continue;
    }
    matched++;

    // old 'points' maps to new 'scorePoints'
    let rowMismatched = false;
    if (oldRow.points !== newRow.scorePoints) rowMismatched = true;
    if (oldRow.averages !== newRow.scoreAverages) rowMismatched = true;
    if (oldRow.stalwart !== newRow.scoreStalwart) rowMismatched = true;
    if (oldRow.pub !== newRow.scorePub) rowMismatched = true;

    for (const f of commonFields) {
        if (oldRow[f] !== newRow[f]) rowMismatched = true;
    }

    if (rowMismatched) {
        mismatched++;
        if (mismatchExamples.length < 5) {
            mismatchExamples.push({ key: k, oldRow, newRow });
        }
    }
}

console.log('old fixture size:', oldFixture.length);
console.log('new snapshot size:', newSnapshot.length);
console.log('matched:', matched);
console.log('missing from new snapshot:', missing);
console.log('mismatched values among matched:', mismatched);
console.log(JSON.stringify(mismatchExamples, null, 2));

