import fs from 'fs';

interface OldRow {
    playerId: number;
    gameDayId: number;
    year: number;
}

const oldFixture: OldRow[] = JSON.parse(
    fs.readFileSync(
        './src/tests/services/data/PlayerRecord.test.json',
        'utf8',
    ),
);
const newSnapshot: Record<string, unknown>[] = JSON.parse(
    fs.readFileSync('./db-snapshot/PlayerRecord.json', 'utf8'),
);

const key = (r: { playerId: number; gameDayId: number; year: number }) =>
    `${r.playerId}-${r.gameDayId}-${r.year}`;

const newByKey = new Map<string, Record<string, unknown>>();
for (const r of newSnapshot) {
    newByKey.set(
        key(r as { playerId: number; gameDayId: number; year: number }),
        r,
    );
}

const regenerated = oldFixture.map((oldRow) => {
    const newRow = newByKey.get(key(oldRow));
    if (!newRow) {
        throw new Error(`No matching row in new snapshot for ${key(oldRow)}`);
    }
    return newRow;
});

fs.writeFileSync(
    './src/tests/services/data/PlayerRecord.test.json',
    JSON.stringify(regenerated, null, 4) + '\n',
);

console.log('Wrote', regenerated.length, 'rows');

